{"command": "cd /workspace/work && python3 - <<'EOF'
import json, subprocess, numpy as np, sys
sys.path.insert(0,'/workspace/work')
from analyze import load
def run(keep, out):
    calls=[{"name":"module_load","arguments":{"path":"/workspace/submission/tune.xm"}}]
    for pat in range(18):
        for ch in range(8):
            if pat==12 and ch==keep: continue
            for r in range(64):
                calls.append({"name":"cell_clear","arguments":{"pattern":pat,"row":r,"channel":ch}})
    calls.append({"name":"module_render","arguments":{"path":out,"rate":44100,"bits":16}})
    json.dump(calls, open('/tmp/t.json','w'))
    subprocess.run(['ft2','batch','/tmp/t.json'], capture_output=True)
    d,sr,_=load(out); x=d[:,0]
    seg=x[int(48*1.6*sr):int(52*1.6*sr)]
    return float(np.sqrt(np.mean(seg**2))), float(np.abs(seg).max())
names={0:'LEAD',1:'LEAD2',2:'ARP',3:'PAD3',4:'BASS',5:'CLAP',6:'KICK',7:'SNR/HAT'}
tot=[]
for ch in range(8):
    r,p = run(ch, f'/tmp/s{ch}.wav')
    tot.append(r)
    print(f"ch{ch} {names[ch]:8s} rms {20*np.log10(r+1e-9):7.1f} dB  peak {p:.3f}")
print("sum of rms (linear):", round(sum(tot),4), " full-mix rms:", round(float(np.sqrt(np.mean((load('/workspace/work/roundtrip.wav')[0][int(48*1.6*44100):int(52*1.6*44100),0])**2))),4))
EOF"}

